    {"step": 2, "tactic": "IAM Role Credential Theft", "technique": "T1528", "what_happened": "At 15:14:14, EXECVE comm='curl' with IMDS token header GET http://169.254.169.254/latest/meta-data/iam/security-credentials/ec2-prod-app-role. Response (JSON with AccessKeyId, SecretAccessKey, Token, Expiration) was redirected to /tmp/p144_imds_20301118_151408/stolen_ec2_creds.json — 1284 bytes FIM-added.", "chain_reason": "Wazuh rule 100512 'FIM: stolen EC2 IAM credentials written to /tmp' fired with rule.mitre.id=T1528."},
    {"step": 3, "tactic": "Stolen Credentials Used from External IP", "technique": "T1528", "what_happened": "At 15:14:32, CloudTrail eventName='GetCallerIdentity' by userIdentity.arn='arn:aws:sts::123456789012:assumed-role/ec2-prod-app-role/i-0a1b2c3d4e5f67890' from sourceIp '79.137.196.42' (NOT the EC2 instance's eu-west-1 IP 10.20.40.42). Credentials exfiltrated off-host and reused from attacker network.", "chain_reason": "Wazuh rule 100510 'AWS CloudTrail: GetCallerIdentity from unexpected principal' fired with rule.mitre.id=T1528."},
    {"step": 4, "tactic": "Post-Credential-Theft IAM Recon + S3 Exfil", "technique": "T1087.004", "what_happened": "At 15:15:22-15:17:30, same stolen credentials (assumed-role i-0a1b2c3d4e5f67890) from 79.137.196.42 invoked: iam:ListAttachedRolePolicies on ec2-prod-app-role + ec2:DescribeInstances + s3:ListBuckets (47 buckets enumerated) + s3:GetObject on 12 objects from 'corp-prod-customer-data'. Egress region eu-west-1 but caller IP from OVH FR.", "chain_reason": "Wazuh rule 100511 'AWS CloudTrail: IAM credential use outside expected region' fired with rule.mitre.id=T1528. Active data exfil through stolen instance role."}
